      "arabicText": "قُلْ يَـٰٓأَيُّهَا ٱلنَّاسُ إِنَّمَآ أَنَا۠ لَكُمْ نَذِيرٌ مُّبِينٌ",
      "translationUrdu": "آپ کہہ دیجئے کہ انسانو ! میں تمہارے لئے صرف واضح طور پر ڈرانے والا ہوں",
      "translationEnglish": "Say, ‘O mankind! I am only a manifest warner to you!’",
