      "arabicText": "يَـٰٓأَيُّهَا ٱلنَّاسُ ضُرِبَ مَثَلٌ فَٱسْتَمِعُوا۟ لَهُۥٓ ۚ إِنَّ ٱلَّذِينَ تَدْعُونَ مِن دُونِ ٱللَّهِ لَن يَخْلُقُوا۟ ذُبَابًا وَلَوِ ٱجْتَمَعُوا۟ لَهُۥ ۖ وَإِن يَسْلُبْهُمُ ٱلذُّبَابُ شَيْـًٔا لَّا يَسْتَنقِذُوهُ مِنْهُ ۚ ضَعُفَ ٱلطَّالِبُ وَٱلْمَطْلُوبُ",
      "translationUrdu": "انسانوں تمہارے لئے ایک مثل بیان کی گئی ہے لہذا اسے غور سے سنو-یہ لوگ جنہیں تم خدا کو چھوڑ کر آواز دیتے ہو یہ سب مل بھی جائیں تو ایک مکھی نہیں پیدا کرسکتے ہیں اور اگر مکھی ان سے کوئی چیز چھین لے تو یہ اس سے چھڑا بھی نہیں سکتے ہیں کہ طالب اور مطلوب دونوں ہی کمزور ہیں",
      "translationEnglish": "O people! Listen to a parable that is being drawn: Indeed those whom you invoke besides Allah will never create [even] a fly even if they all rallied to do so! And if a fly should take away something from them, they can not recover that from it. Feeble is the seeker and the sought",
      "subCategoryKey": "ya_ayyuhan_nas",
