      "arabicText": "وَوَرِثَ سُلَيْمَـٰنُ دَاوُۥدَ ۖ وَقَالَ يَـٰٓأَيُّهَا ٱلنَّاسُ عُلِّمْنَا مَنطِقَ ٱلطَّيْرِ وَأُوتِينَا مِن كُلِّ شَىْءٍ ۖ إِنَّ هَـٰذَا لَهُوَ ٱلْفَضْلُ ٱلْمُبِينُ",
      "translationUrdu": "اور پھر سلیمان داؤد کے وارث ہوئے اور انہوں نے کہا کہ لوگو مجھے پرندوں کی باتوں کا علم دیا گیا ہے اور ہر فضیلت کا ایک حصہ عطا کیا گیا ہے اور یہ خدا کا کھلا ہوا فضل و کرم ہے",
      "translationEnglish": "Solomon inherited from David, and he said, ‘O people! We have been taught the speech of the birds, and we have been given out of everything. Indeed this is a manifest advantage.’",
