      "revelationType": "meccan",
      "arabicText": "يَـٰٓأَيُّهَا ٱلنَّاسُ ٱتَّقُوا۟ رَبَّكُمْ وَٱخْشَوْا۟ يَوْمًا لَّا يَجْزِى وَالِدٌ عَن وَلَدِهِۦ وَلَا مَوْلُودٌ هُوَ جَازٍ عَن وَالِدِهِۦ شَيْـًٔا ۚ إِنَّ وَعْدَ ٱللَّهِ حَقٌّ ۖ فَلَا تَغُرَّنَّكُمُ ٱلْحَيَوٰةُ ٱلدُّنْيَا وَلَا يَغُرَّنَّكُم بِٱللَّهِ ٱلْغَرُورُ",
      "translationUrdu": "انسانو! اپنے پروردگار سے ڈرو اور اس دن سے ڈرو جس دن نہ باپ بیٹے کے کام آئے گا اور نہ بیٹا باپ کے کچھ کام آسکے گا بیشک اللہ کا وعدہ برحق ہے لہٰذا تمہیں زندگانی دنیا دھوکہ میں نہ ڈال دے اور خبردار کوئی دھوکہ دینے والا بھی تمہیں دھوکہ نہ دے سکے",
      "translationEnglish": "O mankind! Be wary of your Lord and fear the day when a father will not atone for his child, nor the child will atone for its father in any wise. Indeed Allah’s promise is true. So do not let the life of the world deceive you, nor let the Deceiver deceive you concerning Allah",
