      "arabicText": "يَـٰٓأَيُّهَا ٱلنَّاسُ ٱذْكُرُوا۟ نِعْمَتَ ٱللَّهِ عَلَيْكُمْ ۚ هَلْ مِنْ خَـٰلِقٍ غَيْرُ ٱللَّهِ يَرْزُقُكُم مِّنَ ٱلسَّمَآءِ وَٱلْأَرْضِ ۚ لَآ إِلَـٰهَ إِلَّا هُوَ ۖ فَأَنَّىٰ تُؤْفَكُونَ",
      "translationUrdu": "انسانو! اپنے اوپراللہ کی نعمت کو یاد کرو کیا اس کے علاوہ بھی کوئی خالق ہے وہی تمہیں آسمان اور زمین سے روزی دیتا ہے اس کے علاوہ کوئی خدا نہیں ہے تو تم کس طرف بہکے چلے جارہے ہو",
      "translationEnglish": "O mankind! Remember Allah’s blessing upon you! Is there any creator other than Allah who provides for you from the sky and the earth? There is no god except Him. So where do you stray",
