      "translationUrdu": "اے ایمان والو جو تمہیں رزق دیا گیا ہے اس میں سے راسِ خدا میں خرچ کرو قبل اسکے کہ وہ دن آجائے جس دن نہ تجارت ہوگی نہ دوستی کام آئے گی اور نہ سفارش. اورکافرین ہی اصل میں ظالمین ہیں",
