      "translationUrdu": "اے ایمان والو- آپس میںایک دوسرے کے مال کو ناحق طریقہ سے نہ کھا جایا کرو ... مگر یہ کہ باہمی رضامندی سے معاملت ہو اور خبردار اپنے نفس کو قتل نہ کرو - اللہ تمہارے حال پر بہت مہربان ہے",
