      "translationUrdu": "ایمان والو خبردار خدا و ر رسول کے سامنے اپنی بات کو آگے نہ بڑھاؤ اور اللہ سے ڈرو بیشک اللہ ہر بات کا سننے والا اور جاننے والا ہے",
