      "period": "Early Medinan",
      "revelationType": "medinan",
      "arabicText": "قُلْ يَـٰٓأَهْلَ ٱلْكِتَـٰبِ تَعَالَوْا۟ إِلَىٰ كَلِمَةٍ سَوَآءٍۭ بَيْنَنَا وَبَيْنَكُمْ أَلَّا نَعْبُدَ إِلَّا ٱللَّهَ وَلَا نُشْرِكَ بِهِۦ شَيْـًٔا وَلَا يَتَّخِذَ بَعْضُنَا بَعْضًا أَرْبَابًا مِّن دُونِ ٱللَّهِ ۚ فَإِن تَوَلَّوْا۟ فَقُولُوا۟ ٱشْهَدُوا۟ بِأَنَّا مُسْلِمُونَ",
      "translationUrdu": "اے پیغمبر آپ کہہ دیں کہ اہلِ کتاب آؤ ایک منصفانہ کلمہ پر اتفاق کرلیں کہ خدا کے علاوہ کسی کی عبادت نہ کریں کسی کو اس کا شریک نہ بنائیں آپس میں ایک دوسرے کو خدائی کا درجہ نہ دیں اور اس کے بعد بھی یہ لوگ منہ موڑیں تو کہہ دیجئے کہ تم لوگ بھی گواہ رہنا کہ ہم لوگ حقیقی مسلمان اور اطاعت گزار ہیں",
      "translationEnglish": "Say, ‘O People of the Book! Come to a common word between us and you: that we will worship no one but Allah, that we will not ascribe any partner to Him, and that some of us will not take some others as lords besides Allah.’ But if they turn away, say, ‘Be witnesses that we have submitted [to Allah].’",
