      "translationUrdu": "اے اہلِ کتاب آخر ابراہیم علیھ السّلام کے بارے میں کیوں بحث کرتے ہو جب کہ توریت اور انجیل ان کے بعد نازل ہوئی ہے کیا تمہیں اتنی بھی عقل نہیں ہے",
