      "arabicText": "قُلْ يَـٰٓأَهْلَ ٱلْكِتَـٰبِ لِمَ تَصُدُّونَ عَن سَبِيلِ ٱللَّهِ مَنْ ءَامَنَ تَبْغُونَهَا عِوَجًا وَأَنتُمْ شُهَدَآءُ ۗ وَمَا ٱللَّهُ بِغَـٰفِلٍ عَمَّا تَعْمَلُونَ",
      "translationUrdu": "کہئے اے اہلِ کتاب کیوں صاحبانِ ایمان کو راسِ خدا سے روکتے ہو اور اس میں کجی تلاش کرتے ہو جبکہ تم خود اس کی صحت کے گواہ ہو اور اللہ تمہارے اعمال سے غافل نہیں ہے",
      "translationEnglish": "Say, ‘O People of the Book! why do you bar the faithful from the way of Allah, seeking to make it crooked, while you are witnesses [to its truthfulness]? And Allah is not oblivious of what you do.’",
