      "arabicText": "يَـٰٓأَهْلَ ٱلْكِتَـٰبِ لَا تَغْلُوا۟ فِى دِينِكُمْ وَلَا تَقُولُوا۟ عَلَى ٱللَّهِ إِلَّا ٱلْحَقَّ ۚ إِنَّمَا ٱلْمَسِيحُ عِيسَى ٱبْنُ مَرْيَمَ رَسُولُ ٱللَّهِ وَكَلِمَتُهُۥٓ أَلْقَىٰهَآ إِلَىٰ مَرْيَمَ وَرُوحٌ مِّنْهُ ۖ فَـَٔامِنُوا۟ بِٱللَّهِ وَرُسُلِهِۦ ۖ وَلَا تَقُولُوا۟ ثَلَـٰثَةٌ ۚ ٱنتَهُوا۟ خَيْرًا لَّكُمْ ۚ إِنَّمَا ٱللَّهُ إِلَـٰهٌ وَٰحِدٌ ۖ سُبْحَـٰنَهُۥٓ أَن يَكُونَ لَهُۥ وَلَدٌ ۘ لَّهُۥ مَا فِى ٱلسَّمَـٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۗ وَكَفَىٰ بِٱللَّهِ وَكِيلًا",
      "translationUrdu": "اے اہل کتاب اپنے دین میں حد سے تجاوز نہ کرو اور خدا کے بارے میں حق کے علاوہ کچھ نہ کہو ---مسیح عیسٰی علیھ السّلام بن مریم صرف اللہ کے رسول اور اس کا کلمہ ہیں جسے مریم کی طرف القائ کیا گیا ہے اور وہ اس کی طرف سے ایک روح ہیں لہذا خدا اور مرسلین پر ایمان لے آؤ اور خبردار تین کا نام بھی نہ لو -اس سے باز آجاؤ کہ اسی میں بھلائی ہے -اللہ فقط خدائے واحد ہے اور وہ اس بات سے منزہ ہے کہ اس کا کوئی بیٹا ہو ,زمین و آسمان میں جو کچھ بھی ہے سب اسی کا ہے اور وہ کفالت و وکالت کے لئے کافی ہے",
      "translationEnglish": "O People of the Book! Do not exceed the bounds in your religion, and do not attribute anything to Allah except the truth. The Messiah, Jesus son of Mary, was only an apostle of Allah, and His Word that He cast toward Mary and a spirit from Him. So have faith in Allah and His apostles, and do not say, ‘[God is] a trinity.’ Relinquish [such a creed]! That is better for you. Allah is but the One God. He is far too immaculate to have any son. To Him belongs whatever is in the heavens and whatever is on the earth, and Allah suffices as trustee",
      "subCategoryKey": "ya_ahl_al_kitab",
