      "translationUrdu": "یقینا وہ لوگ کافر ہیں جن کا کہنا ہے کہ اللہ ہی مسیح علیھ السّلامبن مریم ہیں جبکہ خود مسیح کا کہنا ہے کہ اے بنی اسرائیل اپنے اور میرے پروردگار کی عبادت کرو -جو کوئی اس کا شریک قرار دے گا اس پر خدا نے جنّت حرام کردی ہے اور اس کا انجام جہّنم ہے اور ظالموں کا کوئی مددگار نہ ہوگا",
      "translationEnglish": "They are certainly faithless who say, ‘Allah is the Messiah, son of Mary.’ But the Messiah had said, ‘O Children of Israel! Worship Allah, my Lord, and your Lord. Indeed whoever ascribes partners to Allah, Allah shall forbid him [entry into] paradise, and his refuge shall be the Fire, and the wrongdoers will not have any helpers.’",
