      "translationUrdu": "بنی اسرائیل ! ہم نے تم کو تمہارے دشمن سے نجات دلائی ہے اور طور کی داہنی طرف سے توریت دینے کا وعدہ کیا ہے اور من و سلویٰ بھی نازل کیا ہے",
