      "arabicText": "وَإِذْ قَالَ عِيسَى ٱبْنُ مَرْيَمَ يَـٰبَنِىٓ إِسْرَٰٓءِيلَ إِنِّى رَسُولُ ٱللَّهِ إِلَيْكُم مُّصَدِّقًا لِّمَا بَيْنَ يَدَىَّ مِنَ ٱلتَّوْرَىٰةِ وَمُبَشِّرًۢا بِرَسُولٍ يَأْتِى مِنۢ بَعْدِى ٱسْمُهُۥٓ أَحْمَدُ ۖ فَلَمَّا جَآءَهُم بِٱلْبَيِّنَـٰتِ قَالُوا۟ هَـٰذَا سِحْرٌ مُّبِينٌ",
      "translationUrdu": "اور اس وقت کو یاد کرو جب عیسٰی علیھ السّلام بن مریم علیھ السّلام نے کہا کہ اے بنیآآ اسرائیل میں تمہاری طرف اللہ کا رسول ہوں اپنے پہلے کی کتاب توریت کی تصدیق کرنے والا اور اپنے بعد کے لئے ایک رسول کی بشارت دینے والا ہوں جس کا نام احمد ہے لیکن پھر بھی جب وہ معجزات لے کر آئے تو لوگوں نے کہہ دیا کہ یہ تو کِھلا ہوا جادو ہے",
