      "revelationType": "medinan",
      "arabicText": "ثُمَّ أَنتُمْ هَـٰٓؤُلَآءِ تَقْتُلُونَ أَنفُسَكُمْ وَتُخْرِجُونَ فَرِيقًا مِّنكُم مِّن دِيَـٰرِهِمْ تَظَـٰهَرُونَ عَلَيْهِم بِٱلْإِثْمِ وَٱلْعُدْوَٰنِ وَإِن يَأْتُوكُمْ أُسَـٰرَىٰ تُفَـٰدُوهُمْ وَهُوَ مُحَرَّمٌ عَلَيْكُمْ إِخْرَاجُهُمْ ۚ أَفَتُؤْمِنُونَ بِبَعْضِ ٱلْكِتَـٰبِ وَتَكْفُرُونَ بِبَعْضٍ ۚ فَمَا جَزَآءُ مَن يَفْعَلُ ذَٰلِكَ مِنكُمْ إِلَّا خِزْىٌ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا ۖ وَيَوْمَ ٱلْقِيَـٰمَةِ يُرَدُّونَ إِلَىٰٓ أَشَدِّ ٱلْعَذَابِ ۗ وَمَا ٱللَّهُ بِغَـٰفِلٍ عَمَّا تَعْمَلُونَ",
      "translationUrdu": "لیکن اس کے بعد تم نے قتل و خون شروع کردیا. لوگوں کو علاقہ سے باہر نکالنے لگے اور گناہ وتعدی میں ظالموںکی مدد کرنے لگے حالانکہ کوئی قیدی بن کر آتا ہے تو فدیہ دے کر آزاد بھی کرالیتے ہو جبکہ شروع سے ان کا نکالنا ہی حرام تھا. کیا تم کتاب کے ایک حصّہ پر ایمان رکھتے ہو اور ایک کا انکار کردیتے ہو. ایسا کرنے والوں کی کیا سزاہے سوائے اس کے کہ زندگانی دنیا میں ذلیل ہوں اور قیامت کے دن سخت ترین عذاب کی طرف پلٹاد یئے جائیں گے . اور اللہ تمہارے کرتوت سے بے خبر نہیں ہے",
      "translationEnglish": "Then there you were, killing your folks and expelling a part of your folks from their homes, backing one another against them in sin and aggression! And if they came to you as captives, you would ransom them, though their expulsion itself was forbidden you. What! Do you believe in part of the Book and deny another part? So what is the requital of those of you who do that except disgrace in the life of this world? And on the Day of Resurrection, they shall be consigned to the severest punishment. And Allah is not oblivious of what you do",
