      "arabicText": "وَدَّ كَثِيرٌ مِّنْ أَهْلِ ٱلْكِتَـٰبِ لَوْ يَرُدُّونَكُم مِّنۢ بَعْدِ إِيمَـٰنِكُمْ كُفَّارًا حَسَدًا مِّنْ عِندِ أَنفُسِهِم مِّنۢ بَعْدِ مَا تَبَيَّنَ لَهُمُ ٱلْحَقُّ ۖ فَٱعْفُوا۟ وَٱصْفَحُوا۟ حَتَّىٰ يَأْتِىَ ٱللَّهُ بِأَمْرِهِۦٓ ۗ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ",
      "translationUrdu": "بہت سے اہلِ کتاب یہ چاہتے ہیں کہ تمہیں بھی ایمان کے بعد کافر بنالیں وہ تم سے حسد رکھتے ہیں ورنہ حق ان پر بالکل واضح ہے تو اب تم انہیں معاف کردو اور ان سے درگزر کرو یہاں تک کہ خدا اپنا کوئی حکم بھیج دے اور اللہ ہر شے پر قادر ہے",
