      "arabicText": "أَمْ تَقُولُونَ إِنَّ إِبْرَٰهِـۧمَ وَإِسْمَـٰعِيلَ وَإِسْحَـٰقَ وَيَعْقُوبَ وَٱلْأَسْبَاطَ كَانُوا۟ هُودًا أَوْ نَصَـٰرَىٰ ۗ قُلْ ءَأَنتُمْ أَعْلَمُ أَمِ ٱللَّهُ ۗ وَمَنْ أَظْلَمُ مِمَّن كَتَمَ شَهَـٰدَةً عِندَهُۥ مِنَ ٱللَّهِ ۗ وَمَا ٱللَّهُ بِغَـٰفِلٍ عَمَّا تَعْمَلُونَ",
      "translationUrdu": "کیا تمہارا کہنا یہ ہے کہ ابراہیم علیھ السّلامً اسماعیل علیھ السّلامً اسحاق ً یعقوب علیھ السّلام ا ور اولادیعقوب علیھ السّلام یہودی یا نصرانی تھے تو اے رسول کہہ دیجئے کہ کیا تم خدا سے بہتر جانتے ہو .اور اس سے بڑا ظالم کون ہوگا جس کے پاس خدائی شہادت موجود ہو اور وہ پھر پردہ پوشی کرے اور اللہ تمہارے اعمال سے غافل نہیں ہے",
      "translationEnglish": "[Ask them,] ‘Do you say that Abraham, Ishmael, Isaac, Jacob, and the Tribes were Jews or Christians?’ Say, ‘Is it you who know better, or Allah?’ And who is a greater wrongdoer than someone who conceals a testimony that is with him from Allah? And Allah is not oblivious of what you do",
