      "arabicText": "وَإِذْ أَخَذَ ٱللَّهُ مِيثَـٰقَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَـٰبَ لَتُبَيِّنُنَّهُۥ لِلنَّاسِ وَلَا تَكْتُمُونَهُۥ فَنَبَذُوهُ وَرَآءَ ظُهُورِهِمْ وَٱشْتَرَوْا۟ بِهِۦ ثَمَنًا قَلِيلًا ۖ فَبِئْسَ مَا يَشْتَرُونَ",
      "translationUrdu": "اس موقع کو یاد کرو جب خدا نے جن کو کتاب دی ان سے عہد لیا کہ اسے لوگوں کے لئے بیان کریں گے اور اسے حُھپائیں گے نہیں.. لیکن انہوں نے اس عہد کو پبُ پشت ڈال دیا اور تھوڑی قیمت پر بیچ دیا تو یہ بہت اِرا سودا کیا ہے",
      "translationEnglish": "When Allah made a covenant with those who were given the Book: ‘You shall explain it for the people, and you shall not conceal it,’ they cast it behind their backs and sold it for a paltry gain. How evil is what they buy",
