      "revelationType": "medinan",
      "arabicText": "يَـٰٓأَيُّهَا ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَـٰبَ ءَامِنُوا۟ بِمَا نَزَّلْنَا مُصَدِّقًا لِّمَا مَعَكُم مِّن قَبْلِ أَن نَّطْمِسَ وُجُوهًا فَنَرُدَّهَا عَلَىٰٓ أَدْبَارِهَآ أَوْ نَلْعَنَهُمْ كَمَا لَعَنَّآ أَصْحَـٰبَ ٱلسَّبْتِ ۚ وَكَانَ أَمْرُ ٱللَّهِ مَفْعُولًا",
      "translationUrdu": "اے وہ لوگ جنہیں کتاب دی گئی ہے ہمارے نازل کئے ہوئے قرآن پر ایمان لے آؤ جو تمہاری کتابوں کی تصدیق کرنے والا ہے قبل اس کے کہ ہم تمھارے چہروں کو بگاڑ کر پشت کی طرف پھیر دیں یا ان پر اس طرح لعنت کریں جس طرح ہم نے اصحابِ سبت پر لعنت کی ہے اور اللہ کا حکم بہرحال نافذ ہے",
      "translationEnglish": "O you who were given the Book! Believe in what We have sent down confirming what is with you, before We blot out the faces and turn them backwards, or curse them as We cursed the People of the Sabbath, and Allah’s command is bound to be fulfilled",
