      "arabicText": "لَّيْسَ بِأَمَانِيِّكُمْ وَلَآ أَمَانِىِّ أَهْلِ ٱلْكِتَـٰبِ ۗ مَن يَعْمَلْ سُوٓءًا يُجْزَ بِهِۦ وَلَا يَجِدْ لَهُۥ مِن دُونِ ٱللَّهِ وَلِيًّا وَلَا نَصِيرًا",
      "translationUrdu": "کوئی کام نہ تمہاری امیدوں سے بنے گا نہ اہلِ کتاب کی امیدوں سے- جو بھی اِرا کام کرے گا اس کی سزا بہرحال ملے گی اور خدا کے علاوہ اسے کوئی سرپرست اور مددگار بھی نہیں مل سکتا ہے",
      "translationEnglish": "It will be neither after your hopes nor the hopes of the People of the Book: whoever commits evil shall be requited for it, and he will not find for himself any guardian or helper besides Allah",
