      "revelationType": "medinan",
      "arabicText": "يَسْـَٔلُكَ أَهْلُ ٱلْكِتَـٰبِ أَن تُنَزِّلَ عَلَيْهِمْ كِتَـٰبًا مِّنَ ٱلسَّمَآءِ ۚ فَقَدْ سَأَلُوا۟ مُوسَىٰٓ أَكْبَرَ مِن ذَٰلِكَ فَقَالُوٓا۟ أَرِنَا ٱللَّهَ جَهْرَةً فَأَخَذَتْهُمُ ٱلصَّـٰعِقَةُ بِظُلْمِهِمْ ۚ ثُمَّ ٱتَّخَذُوا۟ ٱلْعِجْلَ مِنۢ بَعْدِ مَا جَآءَتْهُمُ ٱلْبَيِّنَـٰتُ فَعَفَوْنَا عَن ذَٰلِكَ ۚ وَءَاتَيْنَا مُوسَىٰ سُلْطَـٰنًا مُّبِينًا",
      "translationUrdu": "پیغمبر یہ اہل هکتاب آپ سے مطالبہ کرتے ہیں کہ ان پر آسمان سے کوئی کتاب نازل کردیجئے تو انہوں نے موسٰی سے اس سے زیادہ سنگین سوال کیا تھا جب ان سے یہ کہا کہ ہمیں اللہ کو علی الاعلان دکھلا دیجئے تو ان کے ظلم کی بنا پر انہیں ایک بجلی نے اپنی گرفت میں لے لیا پھر انہوں نے ہماری نشانیوں کے آجانے کے باوجود گوسالہ بنالیا تو ہم نے اس سے بھی درگزر کیا اور موسٰی علیھ السّلام کو کھلی ہوئی دلیل عطا کردی",
      "translationEnglish": "The People of the Book ask you to bring down for them a Book from the sky. Certainly they asked Moses for [something] greater than that, for they said, ‘Show us Allah visibly,’ whereat a thunderbolt seized them for their wrongdoing. Then they took up the Calf [for worship], after all the manifest proofs that had come to them. Yet We excused that, and We gave Moses a manifest authority",
