      "nuzulRank": 112,
      "mushafOrder": 5,
      "period": "Late Medinan",
      "revelationType": "medinan",
      "arabicText": "إِنَّآ أَنزَلْنَا ٱلتَّوْرَىٰةَ فِيهَا هُدًى وَنُورٌ ۚ يَحْكُمُ بِهَا ٱلنَّبِيُّونَ ٱلَّذِينَ أَسْلَمُوا۟ لِلَّذِينَ هَادُوا۟ وَٱلرَّبَّـٰنِيُّونَ وَٱلْأَحْبَارُ بِمَا ٱسْتُحْفِظُوا۟ مِن كِتَـٰبِ ٱللَّهِ وَكَانُوا۟ عَلَيْهِ شُهَدَآءَ ۚ فَلَا تَخْشَوُا۟ ٱلنَّاسَ وَٱخْشَوْنِ وَلَا تَشْتَرُوا۟ بِـَٔايَـٰتِى ثَمَنًا قَلِيلًا ۚ وَمَن لَّمْ يَحْكُم بِمَآ أَنزَلَ ٱللَّهُ فَأُو۟لَـٰٓئِكَ هُمُ ٱلْكَـٰفِرُونَ",
      "translationUrdu": "بیشک ہم نے توریت کو نازل کیا ہے جس میں ہدایت اور نور ہے اور اس کے ذریعہ اطاعت گزار انبیائ یہودیوں کے لئے فیصلہ کرتے ہیں اور اللہ والے اور علمائے یہود اس چیز سے فیصلہ کرتے ہیں جس کا کتاب هخدا میں ان کو محافظ بنایا گیا ہے اور جس کے یہ گواہ بھی ہیں لہذا تم ان لوگوں سے نہ ڈرو صرف ہم سے ڈرو اور خبردار تھوڑی سی قیمت کے لئے ہماری آیات کا کاروبار نہ کرنا اور جو بھی ہمارے نازل کئے ہوئے قانون کے مطابق فیصلہ نہ کرے گا وہ سب کافر شمار ہوں گے",
      "translationEnglish": "We sent down the Torah containing guidance and light. The prophets, who had submitted, judged by it for the Jews, and so did the rabbis and the scribes, as they were charged to preserve the Book of Allah and were witnesses to it. So do not fear the people, but fear Me, and do not sell My signs for a paltry gain. Those who do not judge by what Allah has sent down—it is they who are the faithless",
