      "translationUrdu": "اور اگر اہلِ کتاب ایمان لے آتے اور ہم سے ڈرتے رہتے تو ہم ان کے گناہوں کو معاف کردیتے اور انہیں نعمتوں کے باغات میں داخل کردیتے",
