      "translationUrdu": "آپ دیکھیں گے کہ صاحبانِ ایمان سے سب سے زیادہ عداوت رکھنے والے یہودی اور مشرک ہیں اور ان کی محبت سے سب سے زیادہ قریب وہ لوگ ہیں جو کہتے ہیں کہ ہم نصرانی ہیں ...._ یہ اس لئے ہے کہ ان میں بہت سے قسیس اور راہب پائے جاتے ہیں اور یہ متکبر اور برائی کرنے والے نہیں ہیں",
