      "period": "Early Medinan",
      "revelationType": "medinan",
      "arabicText": "إِذَا جَآءَكَ ٱلْمُنَـٰفِقُونَ قَالُوا۟ نَشْهَدُ إِنَّكَ لَرَسُولُ ٱللَّهِ ۗ وَٱللَّهُ يَعْلَمُ إِنَّكَ لَرَسُولُهُۥ وَٱللَّهُ يَشْهَدُ إِنَّ ٱلْمُنَـٰفِقِينَ لَكَـٰذِبُونَ",
      "translationUrdu": "پیغمبر یہ منافقین آپ کے پاس آتے ہیں تو کہتے ہیں کہ ہم گواہی دیتے ہیں کہ آپ اللہ کے رسول ہیں اور اللہ بھی جانتا ہے کہ آپ اس کے رسول ہیںلیکن اللہ گواہی دیتا ہے کہ یہ منافقین اپنے دعویٰ میں جھوٹے ہیں",
      "translationEnglish": "When the hypocrites come to you they say, ‘We bear witness that you are indeed the apostle of Allah.’ Allah knows that you are indeed His Apostle, and Allah bears witness that the hypocrites are indeed liars",
      "subCategoryKey": "surah_munafiqun",
