      "revelationType": "medinan",
      "arabicText": "۞ وَإِذَا رَأَيْتَهُمْ تُعْجِبُكَ أَجْسَامُهُمْ ۖ وَإِن يَقُولُوا۟ تَسْمَعْ لِقَوْلِهِمْ ۖ كَأَنَّهُمْ خُشُبٌ مُّسَنَّدَةٌ ۖ يَحْسَبُونَ كُلَّ صَيْحَةٍ عَلَيْهِمْ ۚ هُمُ ٱلْعَدُوُّ فَٱحْذَرْهُمْ ۚ قَـٰتَلَهُمُ ٱللَّهُ ۖ أَنَّىٰ يُؤْفَكُونَ",
      "translationUrdu": "اور جب آپ انہیں دیکھیں گے تو ان کے جسم بہت اچھے لگیں گے اور بات کریں گے تو اس طرح کہ آپ سننے لگیں لیکن حقیقت میں یہ ایسے ہیں جیسے دیوار سے لگائی ہوئی سوکھی لکڑیاں کہ یہ ہر چیخ کو اپنے ہی خلاف سمجھتے ہیں اور یہ واقعا دشمن ہیں ان سے ہوشیار رہئے خدا انہیں غارت کرے یہ کہاں بہکے چلے جارہے ہیں",
      "translationEnglish": "When you see them, their bodies impress you, and if they speak, you listen to their speech. Yet they are like dry logs set reclining [against a wall]. They suppose every cry is directed against them. They are the enemy, so beware of them. May Allah assail them, where do they stray",
