      "mushafOrder": 63,
      "period": "Early Medinan",
      "revelationType": "medinan",
      "arabicText": "وَإِذَا قِيلَ لَهُمْ تَعَالَوْا۟ يَسْتَغْفِرْ لَكُمْ رَسُولُ ٱللَّهِ لَوَّوْا۟ رُءُوسَهُمْ وَرَأَيْتَهُمْ يَصُدُّونَ وَهُم مُّسْتَكْبِرُونَ",
      "translationUrdu": "اور جب ان سے کہا جاتا ہے کہ آؤ رسول اللہ تمہارے حق میں استغفار کریں گے تو سر پھرا لیتے ہیں اور تم دیکھو گے کہ استکبار کی بنا پر منہ بھی موڑ لیتے ہیں",
      "translationEnglish": "When they are told, ‘Come, that Allah’s Apostle may plead for forgiveness for you,’ they twist their heads, and you see them turn away disdainfully",
      "subCategoryKey": "surah_munafiqun",
