      "period": "Early Medinan",
      "revelationType": "medinan",
      "arabicText": "سَوَآءٌ عَلَيْهِمْ أَسْتَغْفَرْتَ لَهُمْ أَمْ لَمْ تَسْتَغْفِرْ لَهُمْ لَن يَغْفِرَ ٱللَّهُ لَهُمْ ۚ إِنَّ ٱللَّهَ لَا يَهْدِى ٱلْقَوْمَ ٱلْفَـٰسِقِينَ",
      "translationUrdu": "ان کے لئے سب برابر ہے چاہے آپ استغفار کریں یا نہ کریں خدا انہیں بخشنے والا نہیں ہے کہ یقینا اللہ بدکار قوم کی ہدایت نہیں کرتا ہے",
      "translationEnglish": "It is the same for them whether you plead for forgiveness for them, or do not plead for forgiveness for them: Allah will never forgive them. Indeed Allah does not guide the transgressing lot",
      "subCategoryKey": "surah_munafiqun",
