      "arabicText": "وَمِنَ ٱلنَّاسِ مَن يَقُولُ ءَامَنَّا بِٱللَّهِ وَبِٱلْيَوْمِ ٱلْـَٔاخِرِ وَمَا هُم بِمُؤْمِنِينَ",
      "translationUrdu": "کچھ لوگ ایسے بھی ہیں جو یہ کہتے ہیں کہ ہم خدا اور آخرت پر ایمان لائے ہیں حالانکہ وہ صاحب ایمان نہیں ہیں",
      "translationEnglish": "Among the people are those who say, ‘We have faith in Allah and the Last Day,’ but they have no faith",
