      "nuzulRank": 87,
      "mushafOrder": 2,
      "period": "Early Medinan",
      "revelationType": "medinan",
      "arabicText": "يُخَـٰدِعُونَ ٱللَّهَ وَٱلَّذِينَ ءَامَنُوا۟ وَمَا يَخْدَعُونَ إِلَّآ أَنفُسَهُمْ وَمَا يَشْعُرُونَ",
      "translationUrdu": "یہ خدا اور صاحبان ایمان کو دھوکہ دینا چاہتے ہیں حالانکہ اپنے ہی کو دھوکہ دے رہے ہیں اور سمجھتے بھی نہیں ہیں",
      "translationEnglish": "They seek to deceive Allah and those who have faith, yet they deceive no one but themselves, but they are not aware",
      "subCategoryKey": "baqarah_exposition",
      "subCategoryTitleUrdu": "تاسیسِ نفاق (سورۃ البقرہ)",
      "subCategoryTitleEnglish": "Anatomy of Hypocrisy (Al-Baqarah)",
      "scholarlyNoteUrdu": "",
