      "period": "Early Medinan",
      "revelationType": "medinan",
      "arabicText": "فِى قُلُوبِهِم مَّرَضٌ فَزَادَهُمُ ٱللَّهُ مَرَضًا ۖ وَلَهُمْ عَذَابٌ أَلِيمٌۢ بِمَا كَانُوا۟ يَكْذِبُونَ",
      "translationUrdu": "ان کے دلوں میں بیماری ہے اور خدا نے نفاق کی بنا پر اسے اور بھی بڑھا دیا ہے. اب اس جھوٹ کے نتیجہ میں انہیں درد ناک عذاب ملے گا",
      "translationEnglish": "There is a sickness in their hearts; then Allah increased their sickness, and there is a painful punishment for them because of the lies they used to tell",
      "subCategoryKey": "baqarah_exposition",
