      "translationUrdu": "پیغمبر !اگر کوئی قریبی فائدہ یا آسان سفر ہوتا تو یہ ضرور تمہارا اتباع کرتے لیکن ان کے لئے دور کا سفر مشکل بن گیا ہے اور عنقریب یہ خدا کی قسم کھائیں گے کہ اگر ممکن ہوتا تو ہم ضرور آپ کے ساتھ نکل پڑتے -یہ اپنے نفس کو ہلاک کررہے ہیں اور خدا خوب جانتا ہے کہ یہ جھوٹے ہیں",
      "translationEnglish": "Were it an accessible gain or a short journey, they would have surely followed you; but the distance seemed too far to them. Yet they will swear by Allah: ‘If we could, we would have surely gone forth with you.’ They [merely] destroy themselves. Allah knows that they are indeed liars",
