      "translationUrdu": "ان میں وہ لوگ بھی ہیں جو کہتے ہیں کہ ہم کو اجازت دے دیجئے اور فتنہ میں نہ ڈالئے تو آگاہ ہوجاؤ کہ یہ واقعا فتنہ میں گر چکے ہیں اور جہنّم تو کافرین کو ہر طرف سے احاطہ کئے ہوئے ہے",
      "translationEnglish": "Among them there are some who say, ‘Give me leave, and do not put me to temptation.’ Look! They have already fallen into temptation and indeed hell besieges the faithless",
