      "translationUrdu": "منافقین کو یہ خوف بھی ہے کہ کہیں کوئی سورہ نازل ہوکر مسلمانوں کو ان کے دل کے حالات سے باخبر نہ کردے تو آپ کہہ دیجئے کہ تم اور مذاق اڑاؤ اللہ بہرحال اس چیز کو منظر عام پر لے آئے گا جس کا تمہیں خطرہ ہے",
