      "translationUrdu": "منافق مرد اور منافق عورتیں آپس میں سب ایک دوسرے سے ہیں -سب برائیوں کا حکم دیتے ہیں اور نیکیوں سے روکتے ہیں اور اپنے ہاتھوں کو راہ هخدا میں خرچ کرنے سے روکے رہتے ہیں -انہوں نے اللہ کو بھلا دیا ہے تو اللہ نے انہیں بھی نظرانداز کردیا ہے کہ منافقین ہی اصل میں فاسق ہیں",
