      "translationUrdu": "یہ اپنی باتوں پر اللہ کی قسم کھاتے ہیں کہ ایسا نہیں کہا حالانکہ انہوں نے کلمہ کفر کہا ہے اور اپنے اسلام کے بعد کافر ہوگئے ہیں اور وہ ارادہ کیا تھا جو حاصل نہیں کرسکے اور ان کا غصہّ صرف اس بات پر ہے کہ اللہ اور رسول نے اپنے فضل و کرم سے مسلمانوں کو نواز دیا ہے -بہرحال یہ اب بھی توبہ کرلیں تو ان کے حق میں بہتر ہے اور منہ پھیرلیں تو اللہ ان پر دنیا اور آخرت میں دردناک عذاب کرے گا اور روئے زمین پر کوئی ان کا سرپرست اور مددگار نہ ہوگا",
