      "translationUrdu": "اور یہ لوگ پہلے اطاعت کی بات کرتے ہیں- پھر جب آپ کے پاس سے باہر نکلتے ہیں تو ایک گروہ اپنے قول کے خلاف تدبیریں کرتا ہے اور خدا ان کی ان باتوں کو لکھ رہا ہے- آپ ان سے اعراض کریں اور خدا پر بھروسہ کریں اور خدا اس ذمہ داری کے لئے کافی ہے",
