      "translationUrdu": "یہ منافقین تمہارے حالات کا انتظار کرتے رہتے ہیں کہ تمہیں خدا کی طرف سے فتح نصیب ہو تو کہیں گے کیا ہم تمہارے ساتھ نہیں تھے اور اگر کفاّر کو کوئی حصّہ مل جائے گا تو ان سے کہیں گے کہ کیا ہم تم پر غالب نہیں آگئے تھے اور تمہیں مومنین سے بچا نہیں لیا تھا تو اب خدا ہی قیامت کے دن تمہارے درمیان فیصلہ کرے گا اور خدا کفاّر کے لئے صاحبان هایمان کے خلاف کوئی راہ نہیں دے سکتا",
