      "translationUrdu": "یہ تم سے جان چراتے ہیں اور جب خوف سامنے آجائے گا تو آپ دیکھیں گے کہ آپ کی طرف اس طرح دیکھیں گے کہ جیسے ان کی آنکھیں یوں پھر رہی ہیں جیسے موت کی غشی طاری ہو اور جب خوف چلا جائے گا تو آپ پر تیز تر زبانوں کے ساتھ حملہ کریں گے اور انہیں مال غنیمت کی حرص ہوگی یہ لوگ شروع ہی سے ایمان نہیں لائے ہیں لہٰذا خدا نے ان کے اعمال کو برباد کردیا ہے اور خدا کے لئے یہ کام بڑا آسان ہے",
