      "arabicText": "۞ لَّئِن لَّمْ يَنتَهِ ٱلْمُنَـٰفِقُونَ وَٱلَّذِينَ فِى قُلُوبِهِم مَّرَضٌ وَٱلْمُرْجِفُونَ فِى ٱلْمَدِينَةِ لَنُغْرِيَنَّكَ بِهِمْ ثُمَّ لَا يُجَاوِرُونَكَ فِيهَآ إِلَّا قَلِيلًا",
      "translationUrdu": "پھر اگر منافقین اور جن کے دلوں میں بیماری ہے اور مدینہ میںافواہ پھیلانے والے اپنی حرکتوں سے باز نہ آئے تو ہم آپ ہی کو ان پر مسلّط کردیں گے اور پھر یہ آپ کے ہمسایہ میں صرف چند ہی دن رہ پائیں گے",
