      "arabicText": "يَـٰٓأَيُّهَا ٱلنَّبِىُّ إِنَّآ أَحْلَلْنَا لَكَ أَزْوَٰجَكَ ٱلَّـٰتِىٓ ءَاتَيْتَ أُجُورَهُنَّ وَمَا مَلَكَتْ يَمِينُكَ مِمَّآ أَفَآءَ ٱللَّهُ عَلَيْكَ وَبَنَاتِ عَمِّكَ وَبَنَاتِ عَمَّـٰتِكَ وَبَنَاتِ خَالِكَ وَبَنَاتِ خَـٰلَـٰتِكَ ٱلَّـٰتِى هَاجَرْنَ مَعَكَ وَٱمْرَأَةً مُّؤْمِنَةً إِن وَهَبَتْ نَفْسَهَا لِلنَّبِىِّ إِنْ أَرَادَ ٱلنَّبِىُّ أَن يَسْتَنكِحَهَا خَالِصَةً لَّكَ مِن دُونِ ٱلْمُؤْمِنِينَ ۗ قَدْ عَلِمْنَا مَا فَرَضْنَا عَلَيْهِمْ فِىٓ أَزْوَٰجِهِمْ وَمَا مَلَكَتْ أَيْمَـٰنُهُمْ لِكَيْلَا يَكُونَ عَلَيْكَ حَرَجٌ ۗ وَكَانَ ٱللَّهُ غَفُورًا رَّحِيمًا",
      "translationUrdu": "اے پیغمبر ہم نے آپ کے لئے آپ کی بیویوں کو جن کا مہر دے دیا ہے اور کنیزوں کو جنہیں خدا نے جنگ کے بغیر عطا کردیا ہے اور آپ کے چچا کی بیٹیوں کو اور آپ کی پھوپھی کی بیٹیوں کو اور آپ کے ماموں کی بیٹیوں کو اور آپ کی خالہ کی بیٹیوں کو جنہوں نے آپ کے ساتھ ہجرت کی ہے اور اس مومنہ عورت کو جو اپنا نفس نبی کو بخش دے اگر نبی اس سے نکاح کرنا چاہے تو حلال کردیا ہے لیکن یہ صرف آپ کے لئے ہے باقی مومنین کے لئے نہیں ہے. ہمیں معلوم ہے کہ ہم نے ان لوگوں پر ان کی بیویوں اور کنیزوں کے بارے میں کیا فریضہ قرار دیا ہے تاکہ آپ کے لئے کوئی زحمت اور مشقّت نہ ہو اوراللہ بہت زیادہ بخشنے والا اور مہربان ہے",
      "translationEnglish": "O Prophet! Indeed We have made lawful to you your wives whom you have given their dowries, and those whom your right hand owns, of those whom Allah gave you as spoils of war, and the daughters of your paternal uncle, and the daughters of your paternal aunts, and the daughters of your maternal uncle, and the daughters of your maternal aunts who migrated with you, and a faithful woman if she offers herself to the Prophet and the Prophet desires to take her in marriage (a privilege exclusively for you, not for [the rest of] the faithful; We know what We have made lawful for them with respect to their wives and those whom their right hands own, so that there may be no blame on you ), and Allah is all-forgiving, all-merciful",
      "subCategoryKey": "ya_ayyuhan_nabi",
      "subCategoryTitleUrdu": "یا أیها النبی (اے نبیؐ!)",
      "subCategoryTitleEnglish": "O Prophet (Executive Authority & Social Law)",
