      "translationUrdu": "پیغمبر اگر ایمان لانے والی عورتیں آپ کے پاس اس امر پر بیعت کرنے کے لئے آئیں کہ کسی کو خدا کا شریک نہیں بنائیں گی اور چوری نہیں کریں گی - زنا نہیں کریں گی - اولاد کو قتل نہیں کریں گی اور اپنے ہاتھ پاؤں کے سامنے سے کوئی بہتان (لڑکا) لے کر نہیں آئیں گی اور کسی نیکی میں آپ کی مخالفت نہیں کریں گی تو آپ ان سے بیعت کا معاملہ کرلیں اور ان کے حق میں استغفار کریں کہ خدا بڑا بخشنے والا اور مہربان ہے",
      "translationEnglish": "O Prophet! If faithful women come to you, to take the oath of allegiance to you, [pledging] that they shall not ascribe any partners to Allah, that they shall not steal, nor commit adultery, nor kill their children, nor utter any slander that they may have intentionally fabricated, nor disobey you in what is right, then accept their allegiance, and plead for them to Allah for forgiveness. Indeed Allah is all-forgiving, all-merciful",
