      "nuzulRank": 99,
      "mushafOrder": 65,
      "period": "Early Medinan",
      "revelationType": "medinan",
      "arabicText": "يَـٰٓأَيُّهَا ٱلنَّبِىُّ إِذَا طَلَّقْتُمُ ٱلنِّسَآءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ وَأَحْصُوا۟ ٱلْعِدَّةَ ۖ وَٱتَّقُوا۟ ٱللَّهَ رَبَّكُمْ ۖ لَا تُخْرِجُوهُنَّ مِنۢ بُيُوتِهِنَّ وَلَا يَخْرُجْنَ إِلَّآ أَن يَأْتِينَ بِفَـٰحِشَةٍ مُّبَيِّنَةٍ ۚ وَتِلْكَ حُدُودُ ٱللَّهِ ۚ وَمَن يَتَعَدَّ حُدُودَ ٱللَّهِ فَقَدْ ظَلَمَ نَفْسَهُۥ ۚ لَا تَدْرِى لَعَلَّ ٱللَّهَ يُحْدِثُ بَعْدَ ذَٰلِكَ أَمْرًا",
      "translationUrdu": "اے پیغمبر ! جب تم لوگ عورتوں کو طلاق دو تو انہیں عدت کے حساب سے طلاق دو اور پھر عدت کا حساب رکھو اور اللہ سے ڈرتے رہو کہ وہ تمہارا پروردگار ہے اور خبردار انہیں ان کے گھروں سے مت نکالنا اور نہ وہ خود نکلیں جب تک کوئی کِھلا ہوا گناہ نہ کریں - یہ خدائی حدود ہیں اور جو خدائی حدود سے تجاوز کرے گا اس نے اپنے ہی نفس پر ظلم کیا ہے تمہیں نہیں معلوم کہ شاید خدا اس کے بعد کوئی نئی بات ایجاد کردے",
      "translationEnglish": "O Prophet! When you divorce women, divorce them at [the conclusion of] their term and calculate the term, and be wary of Allah, your Lord. Do not turn them out from their homes, nor shall they go out, unless they commit a gross indecency. These are Allah’s bounds, and whoever transgresses the bounds of Allah certainly wrongs himself. You never know maybe Allah will bring off something new later on",
