      "arabicText": "يَـٰٓأَيُّهَا ٱلنَّبِىُّ لِمَ تُحَرِّمُ مَآ أَحَلَّ ٱللَّهُ لَكَ ۖ تَبْتَغِى مَرْضَاتَ أَزْوَٰجِكَ ۚ وَٱللَّهُ غَفُورٌ رَّحِيمٌ",
      "translationUrdu": "پیغمبر آپ اس شے کو کیوں ترک کررہے ہیں جس کو خدا نے آپ کے لئے حلال کیا ہے کیا آپ ازواج کی مرضی کے خواہشمند ہیں اور اللہ بہت بخشنے والا اور مہربان ہے",
