      "period": "Late Medinan",
      "revelationType": "medinan",
      "arabicText": "يَـٰٓأَيُّهَا ٱلنَّبِىُّ جَـٰهِدِ ٱلْكُفَّارَ وَٱلْمُنَـٰفِقِينَ وَٱغْلُظْ عَلَيْهِمْ ۚ وَمَأْوَىٰهُمْ جَهَنَّمُ ۖ وَبِئْسَ ٱلْمَصِيرُ",
      "translationUrdu": "پیغمبر آپ کفر اور منافقین سے جہاد کریں اور ان پر سختی کریں اور ان کا ٹھکانا جہنّم ہے اور وہی بدترین انجام ہے",
      "translationEnglish": "O Prophet! Wage jihad against the faithless and the hypocrites, and be severe with them. Their refuge will be hell, and it is an evil destination",
