      "nuzulRank": 112,
      "mushafOrder": 5,
      "period": "Late Medinan",
      "revelationType": "medinan",
      "arabicText": "۞ يَـٰٓأَيُّهَا ٱلرَّسُولُ لَا يَحْزُنكَ ٱلَّذِينَ يُسَـٰرِعُونَ فِى ٱلْكُفْرِ مِنَ ٱلَّذِينَ قَالُوٓا۟ ءَامَنَّا بِأَفْوَٰهِهِمْ وَلَمْ تُؤْمِن قُلُوبُهُمْ ۛ وَمِنَ ٱلَّذِينَ هَادُوا۟ ۛ سَمَّـٰعُونَ لِلْكَذِبِ سَمَّـٰعُونَ لِقَوْمٍ ءَاخَرِينَ لَمْ يَأْتُوكَ ۖ يُحَرِّفُونَ ٱلْكَلِمَ مِنۢ بَعْدِ مَوَاضِعِهِۦ ۖ يَقُولُونَ إِنْ أُوتِيتُمْ هَـٰذَا فَخُذُوهُ وَإِن لَّمْ تُؤْتَوْهُ فَٱحْذَرُوا۟ ۚ وَمَن يُرِدِ ٱللَّهُ فِتْنَتَهُۥ فَلَن تَمْلِكَ لَهُۥ مِنَ ٱللَّهِ شَيْـًٔا ۚ أُو۟لَـٰٓئِكَ ٱلَّذِينَ لَمْ يُرِدِ ٱللَّهُ أَن يُطَهِّرَ قُلُوبَهُمْ ۚ لَهُمْ فِى ٱلدُّنْيَا خِزْىٌ ۖ وَلَهُمْ فِى ٱلْـَٔاخِرَةِ عَذَابٌ عَظِيمٌ",
      "translationUrdu": "اے رسول ایمان کا دعویٰ کرنے والوں میں جو لوگ کفر کی طرف جلد بازی سے بڑھ رہے ہیں ان کی حرکات سے آپ رنجیدہ نہ ہوں -یہ صرف زبان سے ایمان کا نام لیتے ہیں اور ان کے دل مومن نہیں ہیں اور یہودیوں میں سے بھی بعض ایسے ہیں جو جھوٹی باتیں سنتے ہیں اور دوسری قوم والے جو آپ کے پاس حاضر نہیں ہوئے انہیں سناتے ہیں - یہ کلمات کو ان کی جگہ سے ہٹا دیتے ہیں اور لوگوں سے کہتے ہیں کہ اگر پیغمبر کی طرف سے یہی دیا جائے تو لے لینا اور اگر یہ نہ دیا جائے تو پرہیز کرنا اور جس کے فتنہ کے بارے میں خدا ارادہ کرلے اس کے بارے میں آپ کا کوئی اختیار نہیں ہے یہ وہ افراد ہیں جن کے بارے میں خدا نے یہ ارادہ ہی نہیں کیا کہ زبردستی ان کے دلوں کو پاک کردے گا -ان کے لئے دنیا میں بھی رسوائی ہے اور آخرت میں بھی عذابِ عظیم ہے",
      "translationEnglish": "O Apostle! Do not grieve for those who are active in [promoting] unfaith, such as those who say, ‘We believe’ with their mouths, but whose hearts have no faith, and the Jews who eavesdrop with the aim of [telling] lies [against you] and eavesdrop for other people who do not come to you. They pervert words from their meanings, [and] say, ‘If you are given this, take it, but if you are not given this, beware!’ Yet whomever Allah wishes to mislead, you cannot avail him anything against Allah. They are the ones whose hearts Allah did not desire to purify. For them is disgrace in this world, and there is a great punishment for them in the Hereafter",
