      "revelationType": "medinan",
      "arabicText": "۞ يَـٰٓأَيُّهَا ٱلرَّسُولُ بَلِّغْ مَآ أُنزِلَ إِلَيْكَ مِن رَّبِّكَ ۖ وَإِن لَّمْ تَفْعَلْ فَمَا بَلَّغْتَ رِسَالَتَهُۥ ۚ وَٱللَّهُ يَعْصِمُكَ مِنَ ٱلنَّاسِ ۗ إِنَّ ٱللَّهَ لَا يَهْدِى ٱلْقَوْمَ ٱلْكَـٰفِرِينَ",
      "translationUrdu": "اے پیغمبر آپ اس حکم کو پہنچادیں جو آپ کے پروردگار کی طرف سے نازل کیا گیا ہے اور اگر آپ نے یہ نہ کیا تو گویا اس کے پیغام کو نہیں پہنچایا اور خدا آپ کو لوگوں کے شر سے محفوظ رکھے گا کہ اللہ کافروں کی ہدایت نہیں کرتا ہے",
      "translationEnglish": "O Apostle! Communicate that which has been sent down to you from your Lord, and if you do not, you will not have communicated His message, and Allah shall protect you from the people. Indeed Allah does not guide the faithless lot",
